import string

def is_printable_ascii(s):
    return all(chr(b) in string.printable for b in s)

def find_flag_xor_candidates(filepath, flag_prefix=b'flag{', min_flag_len=10, max_flag_len=128):
    candidates = []
    with open(filepath, 'rb') as f:
        data = f.read()
    n = len(data)
    for offset in range(n - len(flag_prefix) + 1):
        chunk = data[offset:offset+len(flag_prefix)]
        xor_key = bytes([c ^ p for c, p in zip(chunk, flag_prefix)])
        # Now try to reconstruct the full flag:
        # Use the xor_key, repeat as needed
        for flag_len in range(min_flag_len, min(max_flag_len, n-offset)+1):
            key_stream = (xor_key * ((flag_len + len(xor_key) - 1) // len(xor_key)))[:flag_len]
            candidate_bytes = bytes([
                data[offset + i] ^ key_stream[i]
                for i in range(flag_len)
            ])
            if (candidate_bytes[:5] == flag_prefix
                and all(32 <= b < 127 for b in candidate_bytes)  # printable ASCII range
                and b'}' in candidate_bytes):
                # Truncate at first closing brace after 'flag{'
                close_idx = candidate_bytes.find(b'}')
                if close_idx != -1 and close_idx > 6:
                    flag_candidate = candidate_bytes[:close_idx+1].decode(errors='ignore')
                    candidates.append((offset, flag_candidate))
                    break  # Only need longest match at each offset
    return candidates

if __name__ == '__main__':
    import os
    binfile = os.path.join(os.path.dirname(__file__), 'xor.bin')
    if not os.path.exists(binfile):
        print(f"File not found: {binfile}")
        exit(1)
    results = find_flag_xor_candidates(binfile)
    if results:
        print("Offset | Candidate flag")
        for offset, flag in results:
            print(f"{offset:7} | {flag}")
        print("\nMost probable flag candidate(s):")
        for offset, flag in results:
            print(flag)
    else:
        print("No flag candidates found.")
